<script lang="ts">
 import {noteDiagramSpecs,type NoteDiagram} from '$lib/note-diagrams';
 let {diagram}:{diagram:NoteDiagram}=$props();
 const layout=$derived(noteDiagramSpecs[diagram.name].layout);
 const lanes=[[1,2],[2,1],[0,1],[1,2],[2,1]];
</script>
{#snippet card(index:number)}<div class="card"><strong>{diagram.items[index].title}</strong>{#each diagram.items[index].body.split('\n') as line}<p>{line}</p>{/each}</div>{/snippet}
{#snippet down()}<svg class="down" viewBox="0 0 24 24" aria-hidden="true"><path d="M12 3v17m-6-6 6 6 6-6"/></svg>{/snippet}
{#if layout==='csrf-browser'}
 <div class="architecture"><div class="parallel">{@render card(0)}{@render card(1)}</div><p class="boundary">不同的網頁執行安全環境；無法任意互讀資料</p>{@render down()}<section class="browser-group"><h4>{diagram.items[2].title}</h4><p>{diagram.items[2].body}</p><div class="parallel">{@render card(3)}{@render card(4)}</div></section>{@render down()}{@render card(5)}</div>
{:else if layout==='csrf-session'}
 <div class="parallel session">{@render card(0)}{@render card(1)}</div>
{:else if layout==='csrf-exchange'}
 <div class="exchange">{#each diagram.items as item}<section><h4>{item.title}</h4><!-- svelte-ignore a11y_no_noninteractive_tabindex (Keyboard access to local code scrolling.) --><pre role="region" aria-label={item.title} tabindex="0"><code>{item.body}</code></pre></section>{/each}</div>
{:else if layout==='csrf-headers'}
 <dl class="headers">{#each diagram.items as item,i}<div><dt><svg viewBox="0 0 24 24" aria-hidden="true"><path d={i===0?'M3 12h17m-6-6 6 6-6 6':'M21 12H4m6-6-6 6 6 6'}/></svg>{item.title}</dt><dd>{item.body}</dd></div>{/each}</dl>
{:else if layout==='csrf-sequence'}
 <div class="actors" aria-hidden="true"><strong>惡意網頁</strong><strong>Alice Browser</strong><strong>銀行 Server</strong></div>
 <ol class="sequence">{#each diagram.items as item,i}<li style:--from={Math.min(...lanes[i])} style:--to={Math.max(...lanes[i])} class:reply={lanes[i][0]>lanes[i][1]} class={'step step-'+i}><div class="message"><strong>{item.title}</strong><p class="direction">{item.body}</p><svg class="arrow" viewBox="0 0 400 24" preserveAspectRatio="none" aria-hidden="true"><path d={lanes[i][0]<lanes[i][1]?'M2 12H395m-8-7 8 7-8 7':'M398 12H5m8-7-8 7 8 7'}/></svg></div></li>{/each}</ol>
 <p class="boundary">Cookie 未直接交給惡意網頁</p>
{:else if layout==='csrf-origins'||layout==='csrf-samesite'}
 <!-- svelte-ignore a11y_no_noninteractive_tabindex (Keyboard access to local table scrolling.) -->
 <div class="comparison" role="region" aria-label={diagram.caption} tabindex="0"><table><thead><tr><th scope="col">{layout==='csrf-origins'?'其他網址':'請求情境'}</th>{#each (layout==='csrf-origins'?['Origin','Site']:['Strict','Lax','None']) as label}<th scope="col">{label}</th>{/each}</tr></thead><tbody>{#each diagram.items as item}<tr><th scope="row">{item.title}</th>{#each item.body.split('｜') as cell}{@const value=cell.split('：')[1]}<td class:yes={value==='相同'||value==='允許'} class:no={value==='不同'||value==='不允許'}><span aria-hidden="true">{value==='相同'||value==='允許'?'✓':'×'}</span><span>{value}</span></td>{/each}</tr>{/each}</tbody></table></div>
{:else}
 <ol class="token">{#each diagram.items as item,i}<li><span class="number" aria-hidden="true">{i+1}</span><div><strong>{item.title}</strong><p>{item.body}</p></div></li>{/each}</ol>
{/if}
<style>
 strong,h4{font-size:1.125rem;line-height:1.8}h4{margin:.5rem 0}p{font-size:1rem;line-height:1.8;margin:.5rem 0;white-space:pre-line}svg{width:24px;height:24px;fill:none;stroke:currentColor;stroke-width:1.8}.down{display:block;margin:1rem auto;color:#657079}.parallel{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:1rem;margin:1rem 0}.card{padding:1rem;border-radius:12px;background:#f2f4f5;min-width:0;overflow-wrap:anywhere}.session .card{background:transparent;border:1px solid #d8dce0}.session .card p:nth-of-type(2){font-family:ui-monospace,monospace;background:#f2f6f5;color:#18252c;border-radius:5px;padding:.25rem}.boundary{text-align:center;color:#515b61}.browser-group{padding:1rem;border:1px solid #d8dce0;border-radius:12px}.browser-group .card{background:transparent}.exchange section+section{border-top:1px solid #d8dce0;margin-top:1.5rem;padding-top:1rem}pre{white-space:pre-wrap;overflow-wrap:anywhere;overflow-x:auto;background:#f2f6f5;color:#18252c;border-radius:12px;padding:1rem;font-size:1rem;line-height:1.8}code{font-size:inherit;line-height:inherit}pre:focus-visible,.comparison:focus-visible{outline:3px solid #245fe8;outline-offset:3px}.headers{margin:1rem 0}.headers>div{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1.6fr);gap:1rem;padding:1rem 0}.headers>div+div{border-top:1px solid #d8dce0}dt{font-weight:650;font-size:1.125rem;line-height:1.8}dt svg{vertical-align:middle;margin-right:.5rem}dd{margin:0;font-size:1rem;line-height:1.8}.actors{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:.5rem;text-align:center;margin-top:1rem}.actors strong{border:2px solid #94a3b8;background:#e8ecef;padding:.6rem;border-radius:12px}.sequence{list-style:none;padding:0;margin:0;background-image:linear-gradient(#94a3b8 55%,transparent 55%),linear-gradient(#94a3b8 55%,transparent 55%),linear-gradient(#94a3b8 55%,transparent 55%);background-size:2px 20px;background-repeat:repeat-y;background-position:16.666% 0,50% 0,83.333% 0}.sequence li{display:grid;grid-template-columns:repeat(6,minmax(0,1fr));padding:1rem 0;min-width:0}.message{grid-column:calc(var(--from)*2 + 2)/calc(var(--to)*2 + 2);text-align:center;min-width:0}.message strong,.message p{background:#fbfcfd}.arrow{display:block;width:100%;height:24px}.step-0,.step-1{color:#008c83}.step-2{color:#b96500}.step-3{color:#b52323}.step-4{color:#657079}.direction{color:#18252c}.comparison{overflow-x:auto;margin:1rem 0}table{border-collapse:collapse;width:100%;font-size:1rem;line-height:1.8}th,td{padding:.7rem .5rem;text-align:left;border-bottom:1px solid #d8dce0;overflow-wrap:anywhere}th:first-child{width:50%;font-weight:600}td span{display:block}td span:last-child{color:#18252c}.yes{color:#006b39}.no{color:#b52323}.token{list-style:none;padding:0;margin:1rem 0}.token li{display:grid;grid-template-columns:2rem minmax(0,1fr);gap:.75rem;margin:.5rem 0}.number{font-size:1.25rem;line-height:1.8}.token li>div{border-left:2px solid #d8dce0;padding:0 0 1rem .75rem}
 @container(max-width:36rem){.parallel{grid-template-columns:minmax(0,1fr)}.headers>div{grid-template-columns:minmax(0,1fr);gap:.5rem}.actors{display:none}.sequence{background:none}.sequence li{display:block;padding:.8rem 0;border-bottom:1px solid #d8dce0}.message{text-align:left}.message .arrow{width:100%;max-width:20rem}.comparison th,.comparison td{padding:.5rem .25rem}.comparison th:first-child{width:44%}.comparison th{font-size:1rem}.card,.browser-group{padding:.75rem}}
</style>
